// ═══ MUTEX: ReentrantLock (thread-owned, reentrant) ═══
ReentrantLock mutex = new ReentrantLock();
mutex.lock();      // Thread-A owns the lock!
mutex.lock();      // REENTRANT! Thread-A locks again! holdCount=2
mutex.unlock();    // holdCount=1
mutex.unlock();    // holdCount=0 → released!
// Thread-B: mutex.unlock() → IllegalMonitorStateException! Not the owner!

// synchronized is also a mutex:
synchronized (obj) {    // Thread-A owns obj's monitor!
    synchronized (obj) { // REENTRANT! Same monitor, same thread!
    }
}
// Another thread: cannot unlock Thread-A's monitor!

// ═══ SEMAPHORE: no ownership, counting ═══
Semaphore sem = new Semaphore(3);  // 3 permits
sem.acquire();   // Thread-A takes a permit (3→2)
sem.acquire();   // Thread-A takes another (2→1)
// Thread-B:
sem.release();   // Thread-B releases! (1→2) — B didn't acquire! ALLOWED!
sem.release();   // (2→3) — anyone can release!
// No ownership check! No IllegalMonitorStateException!

// ═══ BINARY SEMAPHORE vs MUTEX ═══
Semaphore binary = new Semaphore(1);
// Looks like a mutex: only 1 at a time.
// BUT:
// binary.acquire() by Thread-A
// binary.release() by Thread-B → ALLOWED! (no ownership!)
// binary.acquire() → binary.acquire() by same thread → DEADLOCK! (not reentrant!)

// ═══ COMPARISON TABLE ═══
// Feature           Mutex (Lock/synchronized)  Semaphore
// Ownership         YES (only owner unlocks)    NO (any thread releases)
// Reentrant         YES (same thread re-locks)  NO (re-acquire = block!)
// Concurrent holders 1 (mutual exclusion)       N (counting permits)
// Purpose           Protect critical section    Limit resource access / signaling
// Java class        ReentrantLock, synchronized Semaphore
// Illegal release   ISE / IMSE!                No error (any thread can release!)
// Use case          Balance update              Connection pool, rate limiting
