// ─── File: src/test/java/com/bank/mutexsem/MutexVsSemaphoreTest.java ───
package com.bank.mutexsem;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.locks.*;
import static org.assertj.core.api.Assertions.*;

class MutexVsSemaphoreTest {

    // ═══ Mutex: only owner can unlock ═══
    @Test
    void mutex_onlyOwnerUnlocks() {
        ReentrantLock mutex = new ReentrantLock();
        mutex.lock();  // current thread owns it!

        // Another thread tries to unlock:
        Thread other = new Thread(() -> {
            assertThatThrownBy(mutex::unlock)
                .isInstanceOf(IllegalMonitorStateException.class);
        });
        other.start();
        try { other.join(); } catch (InterruptedException e) { }

        mutex.unlock();  // owner unlocks → OK!
    }

    // ═══ Mutex: reentrant ═══
    @Test
    void mutex_reentrant() {
        ReentrantLock mutex = new ReentrantLock();
        mutex.lock();
        assertThat(mutex.getHoldCount()).isEqualTo(1);
        mutex.lock();  // same thread → reentrant!
        assertThat(mutex.getHoldCount()).isEqualTo(2);
        mutex.unlock();
        mutex.unlock();
        assertThat(mutex.isLocked()).isFalse();
    }

    // ═══ Semaphore: any thread can release ═══
    @Test
    void semaphore_anyThreadReleases() throws InterruptedException {
        Semaphore sem = new Semaphore(0);  // 0 permits!

        // Different thread releases:
        new Thread(() -> sem.release()).start();  // adds a permit!
        Thread.sleep(100);

        assertThat(sem.availablePermits()).isEqualTo(1);
        sem.acquire();  // takes the permit released by another thread!
    }

    // ═══ Binary semaphore: NOT reentrant ═══
    @Test
    void binarySemaphore_notReentrant() throws InterruptedException {
        Semaphore binary = new Semaphore(1);
        binary.acquire();  // takes the 1 permit

        // Same thread tries to acquire again:
        boolean gotIt = binary.tryAcquire(100, TimeUnit.MILLISECONDS);
        assertThat(gotIt).isFalse();  // BLOCKED! Not reentrant!
        // Mutex/ReentrantLock: would succeed (reentrant)!

        binary.release();
    }

    // ═══ Mutex for exclusion, Semaphore for counting ═══
    @Test
    void correctUsage() throws InterruptedException {
        // MUTEX: protect critical section (1 thread!)
        ReentrantLock balanceLock = new ReentrantLock();
        int[] balance = {100000};
        balanceLock.lock();
        try { balance[0] -= 50000; }
        finally { balanceLock.unlock(); }
        assertThat(balance[0]).isEqualTo(50000);

        // SEMAPHORE: limit concurrent access (N threads!)
        Semaphore dbPool = new Semaphore(3);
        assertThat(dbPool.availablePermits()).isEqualTo(3);
        dbPool.acquire(); dbPool.acquire(); dbPool.acquire();
        assertThat(dbPool.availablePermits()).isEqualTo(0);
        dbPool.release(); dbPool.release(); dbPool.release();
    }
}
